#!/usr/bin/env python3
"""BTC15 LIVE DASHBOARD V13 BOOTSTRAP — deploys the read-only dashboard beside the existing full-validation runner. No trading logic changes. No orders."""
from pathlib import Path
import base64,gzip,subprocess,sys,tempfile,os
PAYLOADS = {'BTC15_DASHBOARD_STATE_V2.py': '', 'BTC15_DASHBOARD_LIVE_SERVER_V1.py': '', 'BTC_Kalshi_App_Live_v13.html': '', 'BTC15_RUN_FULL_VALIDATION_WITH_DASHBOARD_V1.py': '', 'README_LIVE_DASHBOARD_V13.txt': ''}
def install():
    d=Path(tempfile.gettempdir())/'btc15_dashboard_v13'
    d.mkdir(parents=True,exist_ok=True)
    for name,b64 in PAYLOADS.items():
        (d/name).write_bytes(gzip.decompress(base64.b64decode(b64)))
    return d
def main():
    d=install()
    wrapper=d/'BTC15_RUN_FULL_VALIDATION_WITH_DASHBOARD_V1.py'
    if '--self-test' in sys.argv:
        p=subprocess.run([sys.executable,str(wrapper),'--self-test'],text=True)
        return p.returncode
    os.execv(sys.executable,[sys.executable,'-u',str(wrapper)])
if __name__=='__main__': raise SystemExit(main())
